// Appends Facial Treatments ids 401-425 (25 questions)
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const ftT=`"Facial Treatments"`, ftTes=`"Tratamientos Faciales"`, ftPt=`"Facial Treatments"`, ftPtes=`"Tratamientos Faciales"`

function fmt(q) {
  return `  { id: ${q.id}, topic: ${ftT}, topic_es: ${ftTes}, psi_topic: ${ftPt}, psi_topic_es: ${ftPtes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const FT = [
  { id: 401, question: "A client requests a facial treatment immediately after having received a series of injectable cosmetic procedures (such as neuromodulator injections) earlier the same day. The most appropriate action is to:", question_es: "Un cliente solicita un tratamiento facial inmediatamente después de haber recibido una serie de procedimientos cosméticos inyectables (como inyecciones de neuromoduladores) ese mismo día. La acción más apropiada es:", options: ["Discuss the recent procedure, explain that facial massage and certain stimulating techniques may need to be postponed for a period of time to avoid affecting the results or healing process, and adjust or reschedule the service accordingly", "Proceed with a deep, stimulating facial massage exactly as originally planned, since injectable procedures have no relationship to facial services", "Refuse to provide any service to the client until the injectable procedure results have completely faded", "Apply firm pressure directly over the injection sites to help the product disperse evenly"], options_es: ["Hablar sobre el procedimiento reciente, explicar que el masaje facial y ciertas técnicas estimulantes pueden necesitar posponerse durante un período de tiempo para evitar afectar los resultados o el proceso de curación, y ajustar o reprogramar el servicio en consecuencia", "Proceder con un masaje facial profundo y estimulante exactamente como se planeó originalmente, ya que los procedimientos inyectables no tienen relación con los servicios faciales", "Negarse a brindar cualquier servicio al cliente hasta que los resultados del procedimiento inyectable hayan desaparecido por completo", "Aplicar presión firme directamente sobre los sitios de inyección para ayudar a que el producto se disperse de manera uniforme"], correct: 0, explanation: "Manipulation, pressure, or heat applied too soon after injectable procedures can affect how the product settles or disperses and may interfere with healing. The professional approach is to ask about recent procedures during consultation, explain why certain techniques should be postponed, and modify or reschedule the service rather than proceeding as usual, refusing service altogether, or doing anything that could affect the injection sites." },
  { id: 402, question: "Why is it important for an esthetician to ask a client about recent sun exposure or planned sun exposure before performing a facial treatment that includes exfoliation?", question_es: "¿Por qué es importante que un esteticista pregunte a un cliente sobre la exposición solar reciente o planificada antes de realizar un tratamiento facial que incluye exfoliación?", options: ["Recently sun-exposed or sunburned skin is more sensitive and prone to irritation from exfoliation, and freshly exfoliated skin is more vulnerable to sun damage afterward, so timing and aftercare guidance (including sun protection) need to be adjusted accordingly", "Sun exposure has no effect on how skin responds to exfoliation treatments", "Asking about sun exposure is only relevant for clients receiving hair removal services, not facial treatments", "Recent sun exposure means the esthetician should increase the intensity of the exfoliation to compensate"], options_es: ["La piel recientemente expuesta al sol o quemada por el sol es más sensible y propensa a la irritación por la exfoliación, y la piel recién exfoliada es más vulnerable al daño solar después, por lo que el momento y las indicaciones de cuidado posterior (incluida la protección solar) deben ajustarse en consecuencia", "La exposición al sol no tiene ningún efecto en cómo responde la piel a los tratamientos de exfoliación", "Preguntar sobre la exposición al sol solo es relevante para los clientes que reciben servicios de depilación, no tratamientos faciales", "La exposición solar reciente significa que el esteticista debe aumentar la intensidad de la exfoliación para compensar"], correct: 0, explanation: "Sun-exposed or sunburned skin has a compromised barrier and heightened sensitivity, making it more vulnerable to irritation from exfoliation. Conversely, exfoliation removes protective surface layers, leaving skin more susceptible to UV damage immediately afterward. Asking about recent and planned sun exposure helps the esthetician decide whether to modify, postpone, or proceed with appropriate aftercare guidance, including reinforcing the importance of sun protection." },
  { id: 403, question: "A client mentions they are pregnant and asks for a facial treatment that includes the use of certain essential oils and a facial massage. The most appropriate response is to:", question_es: "Un cliente menciona que está embarazada y pide un tratamiento facial que incluye el uso de ciertos aceites esenciales y un masaje facial. La respuesta más apropiada es:", options: ["Review which products and essential oils may not be advisable during pregnancy, select pregnancy-appropriate alternatives, and use generally gentle techniques, consulting professional guidance as needed for any uncertain ingredients or procedures", "Proceed with the exact treatment as originally planned, since pregnancy has no bearing on facial treatment planning", "Refuse to provide any facial service whatsoever to a pregnant client under any circumstances", "Substitute all products with the strongest available active ingredients to maximize results before the client's pregnancy progresses further"], options_es: ["Revisar qué productos y aceites esenciales pueden no ser recomendables durante el embarazo, seleccionar alternativas apropiadas para el embarazo y usar técnicas generalmente suaves, consultando orientación profesional según sea necesario para cualquier ingrediente o procedimiento incierto", "Proceder con el tratamiento exacto tal como se planeó originalmente, ya que el embarazo no tiene relación con la planificación del tratamiento facial", "Negarse a proporcionar cualquier servicio facial a una clienta embarazada bajo cualquier circunstancia", "Sustituir todos los productos con los ingredientes activos más fuertes disponibles para maximizar los resultados antes de que avance más el embarazo de la clienta"], correct: 0, explanation: "Pregnancy can change how skin responds to products and treatments, and certain ingredients (including some essential oils and active ingredients) may not be advisable during pregnancy. The appropriate approach is to gather information, select pregnancy-safe alternatives, use gentle techniques, and consult reliable professional resources for guidance on any product or ingredient in question — rather than proceeding without modification, refusing service outright, or intensifying the treatment." },
  { id: 404, question: "Which of the following best describes an appropriate professional boundary regarding a client's request for the esthetician to perform a facial procedure that requires a more advanced license (such as certain forms of microneedling or chemical peels beyond the esthetician's scope)?", question_es: "¿Cuál de las siguientes describe mejor un límite profesional apropiado con respecto a la solicitud de un cliente de que el esteticista realice un procedimiento facial que requiere una licencia más avanzada (como ciertas formas de microagujas o peelings químicos fuera del alcance del esteticista)?", options: ["Politely explain that the requested procedure is outside the esthetician's legal scope of practice, and refer the client to an appropriately licensed professional who can safely perform it", "Perform the procedure anyway as requested, since client satisfaction is the highest priority regardless of licensing requirements", "Tell the client that the procedure does not exist and that nothing similar can help with their concern", "Perform a similar but unlicensed alternative procedure using the same tools and techniques without disclosing the difference to the client"], options_es: ["Explicar cortésmente que el procedimiento solicitado está fuera del alcance legal de práctica del esteticista, y derivar al cliente a un profesional con la licencia apropiada que pueda realizarlo de manera segura", "Realizar el procedimiento de todos modos según lo solicitado, ya que la satisfacción del cliente es la prioridad más alta sin importar los requisitos de licencia", "Decirle al cliente que el procedimiento no existe y que nada similar puede ayudar con su preocupación", "Realizar un procedimiento alternativo similar pero sin licencia usando las mismas herramientas y técnicas sin revelar la diferencia al cliente"], correct: 0, explanation: "Performing procedures beyond one's licensed scope of practice is both a legal violation and a serious safety risk to the client. The professional and ethical response is to clearly (and respectfully) explain the boundary, and refer the client to an appropriately licensed provider — never attempting the procedure regardless of client requests, misrepresenting available options, or performing an undisclosed substitute." },
  { id: 405, question: "Why might an esthetician choose to use a hydrating, sheet-style mask rather than a clay-based mask for a client with very dry, flaky skin and no congestion?", question_es: "¿Por qué podría un esteticista elegir usar una mascarilla hidratante tipo lámina en lugar de una mascarilla a base de arcilla para un cliente con piel muy seca y descamada y sin congestión?", options: ["Hydrating masks are formulated to add and lock in moisture, which addresses the needs of dry, dehydrated skin, whereas clay-based masks are typically more absorbent and drying and could worsen dryness or flakiness in this case", "Clay-based masks are always the superior choice for any skin type or condition, including very dry skin", "Hydrating masks permanently change a client's skin type from dry to normal after a single use", "There is no meaningful difference between hydrating and clay-based masks, so the choice does not matter"], options_es: ["Las mascarillas hidratantes están formuladas para agregar y retener la humedad, lo que aborda las necesidades de la piel seca y deshidratada, mientras que las mascarillas a base de arcilla suelen ser más absorbentes y secantes y podrían empeorar la sequedad o la descamación en este caso", "Las mascarillas a base de arcilla son siempre la mejor opción para cualquier tipo o condición de piel, incluida la piel muy seca", "Las mascarillas hidratantes cambian permanentemente el tipo de piel de un cliente de seca a normal después de un solo uso", "No hay una diferencia significativa entre las mascarillas hidratantes y las de arcilla, por lo que la elección no importa"], correct: 0, explanation: "Selecting the right mask formulation for the client's current skin type and condition is an important part of treatment planning. Hydrating, often gel- or sheet-based masks are designed to deliver and seal in moisture — appropriate for dry or dehydrated skin. Clay-based masks tend to absorb oil and can have a drying effect, which would not be the best choice for skin that is already dry and flaky with no congestion to address." },
  { id: 406, question: "An esthetician is performing a facial on a client and notices what appears to be a cluster of small, fluid-filled blisters on the client's lip area. The most appropriate action is to:", question_es: "Un esteticista está realizando un facial en un cliente y nota lo que parece ser un grupo de pequeñas ampollas llenas de líquido en el área del labio del cliente. La acción más apropiada es:", options: ["Avoid the affected area, use proper precautions to prevent possible spread (such as using disposable or easily sanitized items and washing hands thoroughly), and recommend the client follow up with a healthcare provider, since this may be a contagious viral condition such as a cold sore (herpes simplex)", "Continue the treatment exactly as planned, including direct contact with and product application over the affected area", "Attempt to lance or extract the blisters to relieve the client's discomfort", "Apply a heavy occlusive product directly over the area to seal it and continue with extractions nearby"], options_es: ["Evitar el área afectada, usar las precauciones adecuadas para prevenir una posible propagación (como usar artículos desechables o fácilmente desinfectables y lavarse bien las manos) y recomendar que el cliente consulte a un proveedor de atención médica, ya que esto podría ser una condición viral contagiosa como un herpes labial (herpes simple)", "Continuar el tratamiento exactamente como se planeó, incluido el contacto directo y la aplicación de productos sobre el área afectada", "Intentar perforar o extraer las ampollas para aliviar la incomodidad del cliente", "Aplicar un producto oclusivo pesado directamente sobre el área y continuar con las extracciones cercanas"], correct: 0, explanation: "Clusters of small fluid-filled blisters around the lips are a classic presentation of herpes simplex (cold sores), a contagious viral condition. The esthetician should avoid the area entirely to prevent spreading the virus to other areas of the client's face, to themselves, or to other clients, take appropriate sanitation precautions, and recommend the client see a healthcare provider — never attempting to treat, extract, or work directly over a suspected active viral lesion." },
  { id: 407, question: "Which best explains why an esthetician should avoid performing any extractions or aggressive techniques directly over an area where a client reports recent dermal filler injections?", question_es: "¿Cuál explica mejor por qué un esteticista debe evitar realizar extracciones o técnicas agresivas directamente sobre un área donde un cliente informa haber recibido inyecciones recientes de relleno dérmico?", options: ["Pressure or manipulation soon after filler placement can potentially shift the product, increase swelling or bruising, or otherwise interfere with the results and healing process", "Dermal fillers make the skin more resistant to any kind of manipulation, so technique does not need to be adjusted", "Extractions performed directly over filler sites always improve and prolong the results of the injection", "There is no relationship between injectable treatments and subsequent esthetic services, so no precautions are necessary"], options_es: ["La presión o manipulación poco después de la colocación del relleno puede potencialmente desplazar el producto, aumentar la hinchazón o los moretones, o interferir de otra manera con los resultados y el proceso de curación", "Los rellenos dérmicos hacen que la piel sea más resistente a cualquier tipo de manipulación, por lo que la técnica no necesita ajustarse", "Las extracciones realizadas directamente sobre los sitios de relleno siempre mejoran y prolongan los resultados de la inyección", "No existe ninguna relación entre los tratamientos inyectables y los servicios estéticos posteriores, por lo que no son necesarias precauciones"], correct: 0, explanation: "Dermal filler results can be affected by pressure or manipulation in the treated area, especially soon after the procedure, potentially shifting the product or increasing swelling and bruising. The esthetician should ask about recent injectable procedures during consultation and avoid direct pressure, extraction, or aggressive techniques over those areas, adjusting the treatment plan and timing as appropriate." },
  { id: 408, question: "A returning client mentions that their skin reacted poorly (became red and irritated) to a product used during their last visit. What is the most appropriate first step before beginning today's treatment?", question_es: "Un cliente que regresa menciona que su piel reaccionó mal (se enrojeció e irritó) a un producto utilizado durante su última visita. ¿Cuál es el primer paso más apropiado antes de comenzar el tratamiento de hoy?", options: ["Review the client's record from the previous visit, identify the product that may have caused the reaction, and select alternative products and a modified plan for today's service, communicating clearly with the client throughout", "Use the exact same product again today to see whether the same reaction occurs a second time", "Disregard the client's comment, since one reported reaction does not need to influence today's treatment plan", "Apply a much stronger version of the same product, assuming the prior reaction means the original was too mild to be effective"], options_es: ["Revisar el registro del cliente de la visita anterior, identificar el producto que pudo haber causado la reacción y seleccionar productos alternativos y un plan modificado para el servicio de hoy, comunicándose claramente con el cliente durante todo el proceso", "Usar el mismo producto exacto nuevamente hoy para ver si ocurre la misma reacción por segunda vez", "Ignorar el comentario del cliente, ya que una reacción informada no necesita influir en el plan de tratamiento de hoy", "Aplicar una versión mucho más fuerte del mismo producto, asumiendo que la reacción anterior significa que el original era demasiado suave para ser eficaz"], correct: 0, explanation: "A reported adverse reaction is important clinical information that should directly inform today's plan. Reviewing records (which is why thorough documentation matters), identifying the likely cause, and selecting suitable alternatives helps prevent a repeat reaction and shows the client that their concerns are taken seriously — never re-testing the same product, ignoring the report, or escalating to a stronger version of a product that already caused irritation." },
  { id: 409, question: "Which of the following is the most appropriate way for an esthetician to address a client who appears anxious or nervous before their first facial treatment?", question_es: "¿Cuál de las siguientes es la forma más apropiada para que un esteticista aborde a un cliente que parece ansioso o nervioso antes de su primer tratamiento facial?", options: ["Take time to explain each step of the process in clear, simple terms, answer the client's questions, and check in throughout the service to ensure they remain comfortable", "Begin the treatment immediately without any explanation so the client does not have time to feel more nervous", "Tell the client that their nervousness is unreasonable and that there is nothing to discuss", "Speed through the service as quickly as possible so the anxious client can leave sooner"], options_es: ["Tomarse el tiempo para explicar cada paso del proceso en términos claros y simples, responder las preguntas del cliente y verificar durante todo el servicio que se sienta cómodo", "Comenzar el tratamiento de inmediato sin ninguna explicación para que el cliente no tenga tiempo de sentirse más nervioso", "Decirle al cliente que su nerviosismo es irrazonable y que no hay nada que discutir", "Apresurar el servicio lo más rápido posible para que el cliente ansioso pueda irse antes"], correct: 0, explanation: "Clear communication, patience, and reassurance help build trust and comfort, especially for first-time or anxious clients. Explaining each step, inviting questions, and checking in throughout the service demonstrates professionalism and care, helps the client feel safe and respected, and supports a positive overall experience — far more effective than rushing, dismissing the client's feelings, or withholding information." },
  { id: 410, question: "A client asks the esthetician whether a particular ingredient in a product they purchased elsewhere is safe to use alongside their current prescription topical medication. The most appropriate response is to:", question_es: "Un cliente le pregunta al esteticista si un ingrediente particular en un producto que compró en otro lugar es seguro de usar junto con su medicamento tópico recetado actual. La respuesta más apropiada es:", options: ["Acknowledge the question, share general, accurate information where appropriate, and recommend the client confirm with their prescribing healthcare provider or pharmacist for guidance specific to their medication and health situation", "Confidently assure the client that any over-the-counter ingredient is always safe to combine with any prescription medication", "Refuse to discuss the topic at all and tell the client that ingredient questions are never appropriate to ask an esthetician", "Tell the client to stop using their prescribed medication so there is no possibility of interaction"], options_es: ["Reconocer la pregunta, compartir información general y precisa cuando sea apropiado, y recomendar que el cliente confirme con su proveedor de atención médica que receta o con su farmacéutico para obtener orientación específica para su medicamento y situación de salud", "Asegurarle con confianza al cliente que cualquier ingrediente de venta libre siempre es seguro de combinar con cualquier medicamento recetado", "Negarse a discutir el tema por completo y decirle al cliente que las preguntas sobre ingredientes nunca son apropiadas para hacerle a un esteticista", "Decirle al cliente que deje de usar su medicamento recetado para que no haya posibilidad de interacción"], correct: 0, explanation: "Questions about interactions between cosmetic ingredients and prescription medications touch on medical considerations outside the esthetician's scope to definitively answer. The appropriate response combines being helpful and approachable — sharing general, accurate information when possible — with recognizing the limits of esthetic practice and directing the client to their prescribing provider or pharmacist for a confident, medically informed answer." },
  { id: 411, question: "What is the primary reason an esthetician should avoid performing facial treatments on a client who has an active, visibly inflamed skin infection (such as impetigo) on the area to be treated?", question_es: "¿Cuál es la razón principal por la que un esteticista debe evitar realizar tratamientos faciales en un cliente que tiene una infección cutánea activa y visiblemente inflamada (como el impétigo) en el área a tratar?", options: ["Performing services over an active infection risks worsening the condition for the client, spreading the infection to other areas of their skin, and exposing the esthetician and future clients to contagious organisms", "Active skin infections make the skin more receptive to treatment products and techniques", "There is no risk involved, since infections only affect deeper tissue layers that esthetic treatments cannot reach", "Treating an active infection directly is an effective way for an esthetician to help resolve the underlying condition"], options_es: ["Realizar servicios sobre una infección activa arriesga empeorar la condición para el cliente, propagar la infección a otras áreas de su piel y exponer al esteticista y a futuros clientes a organismos contagiosos", "Las infecciones cutáneas activas hacen que la piel sea más receptiva a los productos y técnicas de tratamiento", "No existe ningún riesgo involucrado, ya que las infecciones solo afectan capas de tejido más profundas que los tratamientos estéticos no pueden alcanzar", "Tratar directamente una infección activa es una forma efectiva de que un esteticista ayude a resolver la condición subyacente"], correct: 0, explanation: "Active, visibly inflamed skin infections (bacterial, viral, or fungal) are generally considered contraindications for esthetic services on the affected area. Manipulating or applying products to infected skin can spread the infection to other areas, worsen the condition, and risk transmitting contagious organisms to the esthetician or future clients through contaminated tools or surfaces. The appropriate response is to avoid the area, follow infection control protocols, and refer the client for medical evaluation." },
  { id: 412, question: "A client asks why their esthetician recommends a consultation and patch test before introducing a new chemical exfoliation treatment, even though they have had similar treatments elsewhere without issue. The best explanation is:", question_es: "Un cliente pregunta por qué su esteticista recomienda una consulta y una prueba de parche antes de introducir un nuevo tratamiento de exfoliación química, aunque haya recibido tratamientos similares en otros lugares sin problemas", options: ["Each formulation, concentration, and individual's skin can respond differently, and a consultation and patch test help confirm that this specific product and approach is appropriate and well tolerated for this client at this time", "Patch testing is simply a formality with no real value, since previous good experiences elsewhere guarantee the same results everywhere", "The client's prior experiences elsewhere make any further consultation or testing completely unnecessary at this location", "Patch testing is required only for clients who have never received any exfoliation treatment before"], options_es: ["Cada formulación, concentración y la piel de cada individuo pueden responder de manera diferente, y una consulta y una prueba de parche ayudan a confirmar que este producto y enfoque específicos son apropiados y bien tolerados para este cliente en este momento", "La prueba de parche es simplemente una formalidad sin ningún valor real, ya que las buenas experiencias previas en otros lugares garantizan los mismos resultados en todas partes", "Las experiencias previas del cliente en otros lugares hacen que cualquier consulta o prueba adicional sea completamente innecesaria en este lugar", "La prueba de parche solo es necesaria para los clientes que nunca antes han recibido ningún tratamiento de exfoliación"], correct: 0, explanation: "Different products contain different formulations, concentrations, and combinations of active ingredients, and an individual's skin can react differently depending on current condition, recent history, or even subtle changes over time. A consultation and patch test specific to the product and provider helps confirm tolerance and appropriateness for that particular treatment — a sound precaution regardless of past experiences elsewhere." },
  { id: 413, question: "A client with very thin, fragile, visibly aging skin and several areas of broken capillaries asks for the most intense exfoliating treatment available. The most appropriate response is to:", question_es: "Un cliente con piel muy fina, frágil, con signos visibles de envejecimiento y varias áreas de capilares rotos pide el tratamiento exfoliante más intenso disponible. La respuesta más apropiada es:", options: ["Explain that the most aggressive option may not be suitable for this skin's current condition, and recommend a gentler approach better matched to its sensitivity, fragility, and vascular concerns, with the option to reassess over time", "Provide the most intense treatment exactly as requested, since client preference always determines the appropriate intensity regardless of skin condition", "Tell the client that no exfoliation of any kind can ever be performed on aging skin", "Recommend the client undergo the intense treatment but apply numbing products beforehand to mask any resulting discomfort"], options_es: ["Explicar que la opción más agresiva puede no ser adecuada para la condición actual de esta piel, y recomendar un enfoque más suave que se adapte mejor a su sensibilidad, fragilidad y preocupaciones vasculares, con la opción de reevaluar con el tiempo", "Proporcionar el tratamiento más intenso exactamente como se solicitó, ya que la preferencia del cliente siempre determina la intensidad apropiada sin importar la condición de la piel", "Decirle al cliente que ningún tipo de exfoliación puede realizarse jamás en piel envejecida", "Recomendar que el cliente se someta al tratamiento intenso pero aplicar productos adormecedores de antemano para enmascarar cualquier malestar resultante"], correct: 0, explanation: "Thin, fragile, visibly aging skin with broken capillaries is more vulnerable to irritation, bruising, and damage from aggressive exfoliation. Matching the treatment intensity to the skin's actual current condition — rather than simply complying with a request for the most intense option — reflects sound professional judgment. A gentler, appropriately selected approach, with potential reassessment and gradual progression over time, better serves the client's skin health and safety." },
  { id: 414, question: "Why is it important for an esthetician to communicate clearly with a client about the expected sensations (such as warmth, tingling, or mild pressure) they may feel during a particular facial procedure, before beginning that step?", question_es: "¿Por qué es importante que un esteticista se comunique claramente con un cliente sobre las sensaciones esperadas (como calor, hormigueo o presión leve) que puede sentir durante un procedimiento facial particular, antes de comenzar ese paso?", options: ["It helps the client feel informed and prepared, reduces anxiety about unexpected sensations, and makes it easier for the client to distinguish between an expected sensation and one that may indicate a problem requiring the esthetician's attention", "It is unnecessary, since clients should never be told what to expect so they can have an unbiased experience", "It guarantees that the client will not feel any sensation at all during the procedure", "It replaces the need to check in with the client or monitor their comfort throughout the procedure"], options_es: ["Ayuda al cliente a sentirse informado y preparado, reduce la ansiedad sobre sensaciones inesperadas y facilita que el cliente distinga entre una sensación esperada y una que pueda indicar un problema que requiera la atención del esteticista", "Es innecesario, ya que nunca se debe decir a los clientes qué esperar para que puedan tener una experiencia imparcial", "Garantiza que el cliente no sentirá ninguna sensación en absoluto durante el procedimiento", "Reemplaza la necesidad de consultar con el cliente o monitorear su comodidad durante todo el procedimiento"], correct: 0, explanation: "Explaining what a client might feel during a procedure helps set realistic expectations, reduces anxiety, and empowers the client to recognize the difference between a normal expected sensation and something that may signal a problem (such as unexpected pain, burning, or stinging) that should be reported immediately. This communication works together with — not instead of — ongoing check-ins throughout the service." },
  { id: 415, question: "Which best describes the appropriate use of an ultrasonic skin scrubber (spatula) device during a facial treatment?", question_es: "¿Cuál describe mejor el uso apropiado de un dispositivo de espátula de limpieza ultrasónica durante un tratamiento facial?", options: ["Using it according to manufacturer guidelines on appropriately prepared, generally healthy skin to gently lift away surface debris and dead skin cells, while avoiding use over open lesions, active infections, or significantly compromised skin", "Using it at maximum intensity directly over active inflamed acne lesions to clear them more thoroughly", "Using it as a complete substitute for cleansing, analysis, and all other facial treatment steps", "Using it without any client consultation, since the device cannot cause any type of reaction or discomfort"], options_es: ["Usarlo según las pautas del fabricante en piel generalmente sana y adecuadamente preparada para levantar suavemente los residuos de la superficie y las células muertas de la piel, evitando su uso sobre lesiones abiertas, infecciones activas o piel significativamente comprometida", "Usarlo a máxima intensidad directamente sobre lesiones de acné inflamado activo para eliminarlas más a fondo", "Usarlo como sustituto completo de la limpieza, el análisis y todos los demás pasos del tratamiento facial", "Usarlo sin ninguna consulta con el cliente, ya que el dispositivo no puede causar ningún tipo de reacción o malestar"], correct: 0, explanation: "Ultrasonic skin scrubbers use vibration to gently lift away surface debris, oil, and dead skin cells from properly prepared skin. As with any device, it should be used according to manufacturer instructions, suited to the client's skin condition, and avoided over open lesions, active infections, or significantly compromised or inflamed areas — and it complements, rather than replaces, the other essential steps of a complete facial treatment." },
  { id: 416, question: "When selecting a facial treatment plan for a client with a documented nut allergy, the esthetician should:", question_es: "Al seleccionar un plan de tratamiento facial para un cliente con una alergia documentada a las nueces, el esteticista debe:", options: ["Carefully review product ingredient lists for nut-derived oils or extracts (such as almond, hazelnut, or other tree nut ingredients) and select alternative products that avoid the allergen entirely", "Disregard the noted allergy, since topical exposure to allergens cannot cause any type of reaction", "Use the product containing the allergen anyway but apply it only to a very small area of the face", "Recommend the client take an over-the-counter antihistamine before the appointment so any product can be used safely"], options_es: ["Revisar cuidadosamente las listas de ingredientes de los productos en busca de aceites o extractos derivados de nueces (como almendra, avellana u otros ingredientes de frutos secos de árbol) y seleccionar productos alternativos que eviten el alérgeno por completo", "Ignorar la alergia anotada, ya que la exposición tópica a los alérgenos no puede causar ningún tipo de reacción", "Usar el producto que contiene el alérgeno de todos modos pero aplicarlo solo en un área muy pequeña de la cara", "Recomendar que el cliente tome un antihistamínico de venta libre antes de la cita para que se pueda usar cualquier producto de manera segura"], correct: 0, explanation: "Topical exposure to known allergens can trigger reactions ranging from localized irritation to more significant responses. A documented allergy must be taken seriously: the esthetician should carefully check ingredient lists for any related allergens (recognizing that nut-derived ingredients can appear under various names) and select alternative, allergen-free products — never using a known allergen 'in moderation' or relying on the client to medicate themselves to tolerate it." },
  { id: 417, question: "A client asks the esthetician to recommend how often they should schedule professional facial treatments to maintain healthy-looking skin. An appropriate, professionally sound response would:", question_es: "Un cliente le pide al esteticista que le recomiende con qué frecuencia debe programar tratamientos faciales profesionales para mantener una piel de aspecto saludable. Una respuesta apropiada y profesionalmente sólida:", options: ["Take into account the client's skin type, current concerns, treatment goals, and how their skin has responded so far, and offer a general recommendation while explaining that the plan can be adjusted as their skin changes over time", "Recommend the same fixed frequency for every client regardless of their skin type, concerns, or how their skin responds to treatment", "Avoid giving any recommendation at all, since suggesting a treatment frequency could be considered inappropriate", "Recommend the client schedule treatments as frequently as financially possible, since more frequent visits always produce proportionally better results regardless of the skin's needs"], options_es: ["Tener en cuenta el tipo de piel del cliente, las preocupaciones actuales, los objetivos del tratamiento y cómo ha respondido su piel hasta el momento, y ofrecer una recomendación general explicando que el plan puede ajustarse a medida que su piel cambie con el tiempo", "Recomendar la misma frecuencia fija para cada cliente sin importar su tipo de piel, sus preocupaciones o cómo responde su piel al tratamiento", "Evitar dar cualquier recomendación, ya que sugerir una frecuencia de tratamiento podría considerarse inapropiado", "Recomendar que el cliente programe tratamientos con la mayor frecuencia posible financieramente, ya que las visitas más frecuentes siempre producen resultados proporcionalmente mejores sin importar las necesidades de la piel"], correct: 0, explanation: "A thoughtful recommendation is individualized — based on the client's specific skin type, concerns, goals, and observed response to treatment — rather than a one-size-fits-all answer. Explaining that the plan may be adjusted over time as the skin changes reflects realistic, client-centered guidance, and avoids both unhelpful vagueness and recommendations driven mainly by maximizing visit frequency rather than the client's actual needs." },
  { id: 418, question: "Which best describes an appropriate way for an esthetician to incorporate a client's stated budget into their facial treatment and homecare recommendations?", question_es: "¿Cuál describe mejor una manera apropiada para que un esteticista incorpore el presupuesto declarado de un cliente en sus recomendaciones de tratamiento facial y cuidado en el hogar?", options: ["Listen to the client's budget considerations, prioritize the most impactful products and services for their specific concerns, and offer reasonable alternatives where possible, without pressuring the client to exceed what they are comfortable spending", "Ignore any mention of budget and recommend only the most expensive products and services available", "Refuse to provide any service or recommendation to a client who mentions having a limited budget", "Tell the client that effective skin care is impossible to achieve without spending a significant amount of money"], options_es: ["Escuchar las consideraciones de presupuesto del cliente, priorizar los productos y servicios más impactantes para sus preocupaciones específicas y ofrecer alternativas razonables cuando sea posible, sin presionar al cliente para que gaste más de lo que se siente cómodo", "Ignorar cualquier mención del presupuesto y recomendar solo los productos y servicios más caros disponibles", "Negarse a brindar cualquier servicio o recomendación a un cliente que menciona tener un presupuesto limitado", "Decirle al cliente que es imposible lograr un cuidado de la piel eficaz sin gastar una cantidad significativa de dinero"], correct: 0, explanation: "Respecting a client's stated budget while still providing valuable guidance reflects client-centered, ethical practice. This means prioritizing the products or services likely to have the greatest impact on the client's specific concerns, suggesting reasonable alternatives, and avoiding pressure tactics — building trust and long-term rapport rather than focusing solely on maximizing sales regardless of the client's circumstances." },
  { id: 419, question: "Why might an esthetician choose to take 'before' photographs (with the client's informed consent) at the start of a treatment series targeting a specific concern, such as textural irregularities or hyperpigmentation?", question_es: "¿Por qué podría un esteticista optar por tomar fotografías de 'antes' (con el consentimiento informado del cliente) al comienzo de una serie de tratamientos dirigidos a una preocupación específica, como irregularidades de textura o hiperpigmentación?", options: ["Photographs can provide an objective visual record to track progress over the course of a treatment series, supporting more informed adjustments to the plan and helping the client see meaningful changes over time", "Photographs are taken solely so they can be shared publicly without the client's knowledge or consent", "Photographs eliminate the need for any further verbal consultation throughout the series", "Photographs guarantee that the treatment series will produce a specific, predetermined outcome"], options_es: ["Las fotografías pueden proporcionar un registro visual objetivo para seguir el progreso a lo largo de una serie de tratamientos, apoyando ajustes más informados al plan y ayudando al cliente a ver cambios significativos con el tiempo", "Las fotografías se toman únicamente para poder compartirlas públicamente sin el conocimiento o consentimiento del cliente", "Las fotografías eliminan la necesidad de cualquier consulta verbal adicional durante toda la serie", "Las fotografías garantizan que la serie de tratamientos producirá un resultado específico y predeterminado"], correct: 0, explanation: "With proper informed consent, 'before' photographs (and follow-up images over time) can provide an objective way to track changes that may be subtle day-to-day but meaningful over weeks or months. This supports the esthetician in evaluating whether the current plan is working and adjusting as needed, and can help clients recognize gradual improvements — but photographs must always be handled according to consent and confidentiality standards, never shared without permission, and are not a guarantee of specific results." },
  { id: 420, question: "A client mentions that they have a known allergy to a common preservative found in many cosmetic products. What is the most appropriate professional response?", question_es: "Un cliente menciona que tiene una alergia conocida a un conservante común que se encuentra en muchos productos cosméticos. ¿Cuál es la respuesta profesional más apropiada?", options: ["Document the allergy, carefully review ingredient lists for that preservative (and any closely related compounds) before selecting products, and choose alternatives that avoid the allergen for this client's services", "Use standard products as usual, since preservatives in cosmetic products cannot cause allergic reactions", "Tell the client that allergies to cosmetic ingredients are extremely rare and therefore unlikely to be a real concern", "Apply the product containing the allergen to a small test area during the service itself to confirm whether a reaction occurs"], options_es: ["Documentar la alergia, revisar cuidadosamente las listas de ingredientes en busca de ese conservante (y cualquier compuesto estrechamente relacionado) antes de seleccionar productos, y elegir alternativas que eviten el alérgeno para los servicios de este cliente", "Usar los productos estándar como de costumbre, ya que los conservantes en los productos cosméticos no pueden causar reacciones alérgicas", "Decirle al cliente que las alergias a los ingredientes cosméticos son extremadamente raras y, por lo tanto, es poco probable que sean una preocupación real", "Aplicar el producto que contiene el alérgeno en una pequeña área de prueba durante el servicio mismo para confirmar si ocurre una reacción"], correct: 0, explanation: "Preservatives are common ingredients in many cosmetic formulations, and allergic or sensitivity reactions to specific preservatives do occur. Taking a reported allergy seriously means documenting it clearly, carefully reviewing product labels (since the same or related compounds may appear under different names), and proactively selecting suitable alternatives — not testing a known allergen on the client during the service itself or dismissing the concern." },
  { id: 421, question: "Which of the following best illustrates an esthetician maintaining appropriate professional boundaries when a client begins to discuss a personal medical diagnosis unrelated to their skin during a facial treatment?", question_es: "¿Cuál de las siguientes ilustra mejor a un esteticista manteniendo límites profesionales apropiados cuando un cliente comienza a hablar sobre un diagnóstico médico personal no relacionado con su piel durante un tratamiento facial?", options: ["Listening respectfully and with empathy, while being careful not to offer medical opinions, diagnoses, or treatment advice on the topic, and redirecting focus to the esthetic service and any relevant skin care considerations", "Offering a detailed personal opinion about the best course of medical treatment for the diagnosis described", "Abruptly telling the client that personal topics may never be discussed during any service", "Sharing details of the conversation with other clients later in the day as a way to build rapport with them"], options_es: ["Escuchar con respeto y empatía, teniendo cuidado de no ofrecer opiniones médicas, diagnósticos o consejos de tratamiento sobre el tema, y redirigir el enfoque hacia el servicio estético y cualquier consideración relevante para el cuidado de la piel", "Ofrecer una opinión personal detallada sobre el mejor curso de tratamiento médico para el diagnóstico descrito", "Decirle abruptamente al cliente que los temas personales nunca pueden discutirse durante ningún servicio", "Compartir detalles de la conversación con otros clientes más tarde en el día como una forma de generar confianza con ellos"], correct: 0, explanation: "Maintaining professional boundaries means listening respectfully without overstepping into medical advice or diagnosis (which is outside the esthetician's scope and could cause harm), while gently guiding the conversation back toward the service and any esthetically relevant considerations. It also means respecting client confidentiality at all times — never repeating personal information shared by one client to others." },
  { id: 422, question: "Why is ongoing continuing education important for a licensed esthetician beyond simply meeting renewal requirements?", question_es: "¿Por qué es importante la educación continua en curso para un esteticista licenciado más allá de simplemente cumplir con los requisitos de renovación?", options: ["It helps the esthetician stay informed about new techniques, products, safety practices, and regulatory updates, supporting safer, more effective, and more current client care over time", "Continuing education has no real impact on the quality of services an esthetician provides to clients", "Continuing education is solely a way for course providers to generate revenue from licensed professionals", "Once a license is obtained, no further learning is ever necessary to provide quality services"], options_es: ["Ayuda al esteticista a mantenerse informado sobre nuevas técnicas, productos, prácticas de seguridad y actualizaciones regulatorias, apoyando una atención al cliente más segura, efectiva y actualizada con el tiempo", "La educación continua no tiene ningún impacto real en la calidad de los servicios que un esteticista brinda a los clientes", "La educación continua es únicamente una forma de que los proveedores de cursos generen ingresos de los profesionales licenciados", "Una vez obtenida una licencia, ya no es necesario seguir aprendiendo para brindar servicios de calidad"], correct: 0, explanation: "The esthetics field continues to evolve — new products, techniques, devices, safety standards, and regulations emerge over time. Beyond satisfying license renewal requirements, ongoing education helps a professional stay current, refine their skills, adapt to new information, and ultimately provide safer, more effective, and more informed care to their clients throughout their career." },
  { id: 423, question: "A client returning for a follow-up facial mentions that a homecare product recommended at their last visit caused mild dryness, but they continued using it daily as instructed. What is the most appropriate response?", question_es: "Un cliente que regresa para un facial de seguimiento menciona que un producto de cuidado en casa recomendado en su última visita le causó sequedad leve, pero continuó usándolo diariamente según las indicaciones. ¿Cuál es la respuesta más apropiada?", options: ["Acknowledge the feedback, reassess the product and usage recommendations (such as adjusting frequency or pairing it with a hydrating product), and clearly explain to the client that they should not continue using a product that is causing discomfort without first checking back in", "Tell the client that mild dryness is always desirable and that they should continue using the product exactly as before with no changes", "Instruct the client to increase the frequency of use to push through the dryness more quickly", "Dismiss the concern entirely, since the client did not stop using the product on their own"], options_es: ["Reconocer la retroalimentación, reevaluar las recomendaciones del producto y de uso (como ajustar la frecuencia o combinarlo con un producto hidratante) y explicarle claramente al cliente que no debe seguir usando un producto que le causa molestias sin antes consultar", "Decirle al cliente que la sequedad leve siempre es deseable y que debe continuar usando el producto exactamente como antes sin cambios", "Indicar al cliente que aumente la frecuencia de uso para superar la sequedad más rápidamente", "Descartar la preocupación por completo, ya que el cliente no dejó de usar el producto por su cuenta"], correct: 0, explanation: "Listening to and validating client feedback about homecare products is an important part of ongoing care. The esthetician should reassess the recommendation (perhaps adjusting frequency, layering with a hydrating product, or substituting an alternative), and also use the moment to reinforce that clients should reach out if a recommended product causes ongoing discomfort, rather than continuing to use something that is not well tolerated." },
  { id: 424, question: "Which best describes a responsible approach for an esthetician when introducing a client to a new, more advanced treatment modality (such as a higher-strength chemical exfoliation or a new device-based service) for the first time?", question_es: "¿Cuál describe mejor un enfoque responsable para un esteticista al presentar a un cliente una nueva modalidad de tratamiento más avanzada (como una exfoliación química de mayor concentración o un nuevo servicio basado en dispositivos) por primera vez?", options: ["Start conservatively — explaining the modality, setting realistic expectations, beginning with a gentler approach or shorter exposure where appropriate, and monitoring the client's response closely before considering any progression", "Begin immediately with the strongest, most intensive version of the modality to demonstrate its full potential on the first visit", "Skip any explanation, since clients do not need to understand what is being done to them during a service", "Use the new modality without adjusting any previously planned steps of the existing treatment routine"], options_es: ["Comenzar de manera conservadora — explicando la modalidad, estableciendo expectativas realistas, comenzando con un enfoque más suave o una exposición más corta cuando sea apropiado, y monitoreando de cerca la respuesta del cliente antes de considerar cualquier progresión", "Comenzar de inmediato con la versión más fuerte e intensiva de la modalidad para demostrar todo su potencial en la primera visita", "Omitir cualquier explicación, ya que los clientes no necesitan entender lo que se les está haciendo durante un servicio", "Usar la nueva modalidad sin ajustar ningún paso previamente planeado de la rutina de tratamiento existente"], correct: 0, explanation: "Introducing any new, more advanced modality calls for a cautious, stepwise approach: clearly explaining what the client can expect, starting conservatively (lower strength, shorter duration, or gentler settings where applicable), and closely observing how their skin responds before considering increases in intensity or frequency. This protects the client's safety and comfort while allowing the esthetician to gather meaningful information about how that individual's skin responds." },
  { id: 425, question: "A new client's intake form indicates they have a history of keloid scarring (raised, excessive scar tissue formation after skin injury). Which consideration is most relevant when planning their facial treatment?", question_es: "El formulario de admisión de un nuevo cliente indica que tiene antecedentes de cicatrices queloides (formación de tejido cicatricial elevado y excesivo después de una lesión en la piel). ¿Cuál consideración es más relevante al planificar su tratamiento facial?", options: ["Avoiding procedures that could cause significant trauma, injury, or aggressive manipulation of the skin, since keloid-prone skin can form excessive scar tissue in response to even relatively minor injuries", "Recommending the most aggressive exfoliation and extraction techniques available, since keloid-prone skin heals more efficiently than typical skin", "Disregarding the history entirely, since keloid formation only relates to surgical procedures and has no bearing on esthetic treatments", "Performing a test injury on a small area of skin to determine whether a keloid will form before proceeding with the full service"], options_es: ["Evitar procedimientos que puedan causar trauma significativo, lesión o manipulación agresiva de la piel, ya que la piel propensa a queloides puede formar tejido cicatricial excesivo en respuesta incluso a lesiones relativamente menores", "Recomendar las técnicas de exfoliación y extracción más agresivas disponibles, ya que la piel propensa a queloides cicatriza de manera más eficiente que la piel típica", "Ignorar por completo el historial, ya que la formación de queloides solo se relaciona con procedimientos quirúrgicos y no tiene relación con los tratamientos estéticos", "Realizar una lesión de prueba en una pequeña área de la piel para determinar si se formará un queloide antes de proceder con el servicio completo"], correct: 0, explanation: "Individuals prone to keloid scarring can develop excessive, raised scar tissue in response to even minor skin trauma — including aggressive extractions, certain forms of exfoliation, or other manipulations that injure the skin. This history should lead the esthetician to favor gentler techniques, avoid unnecessary trauma to the skin, and remain alert to any signs of irritation or injury, adjusting the plan to minimize risk for this client." },
]

let out = readFileSync(FILE, 'utf8')
out += FT.map(fmt).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${FT.length} Facial Treatments (ids ${FT[0].id}–${FT[FT.length-1].id})`)
